func (t KeyScope) AsKeyScope0() (KeyScope0, error) {
	var body KeyScope0
	err := json.Unmarshal(t.union, &body)
	return body, err
}

// FromKeyScope0 overwrites any union data inside the KeyScope as the provided KeyScope0
func (t *KeyScope) FromKeyScope0(v KeyScope0) error {
	b, err := json.Marshal(v)
	t.union = b
	return err
}

// MergeKeyScope0 performs a merge with any union data inside the KeyScope, using the provided KeyScope0
func (t *KeyScope) MergeKeyScope0(v KeyScope0) error {
	b, err := json.Marshal(v)
	if err != nil {
		return err
	}

	merged, err := runtime.JSONMerge(t.union, b)
	t.union = merged
	return err
}

